<?php
declare(strict_types=1);
require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../config/db.php';require_once __DIR__.'/../../includes/audit.php';
if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;}verify_csrf();
requireModulePermission('expenses','create');
try{$title=trim((string)($_POST['expense_title']??''));$cat=(int)($_POST['category_id']??0);$amount=(float)($_POST['amount']??0);$method=(string)($_POST['payment_method']??'Cash');$date=(string)($_POST['expense_date']??date('Y-m-d'));$desc=trim((string)($_POST['description']??''));if($title===''||$cat<=0||$amount<=0)throw new RuntimeException('Complete all required expense fields.');$categoryCheck=$conn->prepare("SELECT id FROM expense_categories WHERE id=? AND status='Active' LIMIT 1");$categoryCheck->execute([$cat]);if(!$categoryCheck->fetchColumn())throw new RuntimeException('Select an active expense category.');if(!in_array($method,['Cash','M-Pesa','Bank','Cheque','Other'],true))throw new RuntimeException('Invalid payment method.');$number='TMP-'.strtoupper(bin2hex(random_bytes(8)));$hasCashShiftColumn=(bool)$conn->query("SHOW COLUMNS FROM expenses LIKE 'cash_shift_id'")->fetch();if($hasCashShiftColumn){$cashShiftId=null;if($method==='Cash'){$shiftQ=$conn->prepare("SELECT id FROM cash_shifts WHERE user_id=? AND status='Open' ORDER BY id DESC LIMIT 1");$shiftQ->execute([(int)$_SESSION['user_id']]);$cashShiftId=$shiftQ->fetchColumn()?:null;if(!$cashShiftId&&hasModulePermission('cash_management','create'))throw new RuntimeException('Open your cashier shift before recording a cash expense.');}$s=$conn->prepare("INSERT INTO expenses (expense_number,category_id,user_id,expense_title,amount,payment_method,expense_date,description,cash_shift_id) VALUES (?,?,?,?,?,?,?,?,?)");$s->execute([$number,$cat,(int)$_SESSION['user_id'],$title,$amount,$method,$date,$desc?:null,$cashShiftId]);}else{$s=$conn->prepare("INSERT INTO expenses (expense_number,category_id,user_id,expense_title,amount,payment_method,expense_date,description) VALUES (?,?,?,?,?,?,?,?)");$s->execute([$number,$cat,(int)$_SESSION['user_id'],$title,$amount,$method,$date,$desc?:null]);}$expenseId=(int)$conn->lastInsertId();$number='EXP-'.date('ymd').'-'.str_pad((string)$expenseId,5,'0',STR_PAD_LEFT);$conn->prepare("UPDATE expenses SET expense_number=? WHERE id=?")->execute([$number,$expenseId]);$log=$conn->prepare("INSERT INTO activity_logs (user_id,action,module,description,ip_address) VALUES (?,?,?,?,?)");$log->execute([(int)$_SESSION['user_id'],'Create','Expenses','Recorded expense '.$number.' KES '.number_format($amount,2),$_SERVER['REMOTE_ADDR']??null]);recordAuditEvent($conn,'Create','expenses','Recorded expense '.$number.' KES '.number_format($amount,2),'expense',$expenseId,null,['amount'=>$amount,'payment_method'=>$method,'expense_title'=>$title]);$_SESSION['expense_flash']='Expense '.$number.' recorded successfully.';}catch(Throwable $e){$_SESSION['expense_flash']='Expense failed: '.$e->getMessage();}header('Location: index.php');exit;